277	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
278	  if (segment.type === 'thinking') {
279	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
280	    return;
281	  }
282	  commitAndClear(ws, session, state, 'thinkingIndex');
283	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
284	}
285	
286	function streamSegment(
287	  ws: WebSocket,
288	  session: ChatSession,
289	  state: StreamState,
290	  key: StateIndexKey,
291	  createEntry: EntryFactory,
292	  content: string
293	): void {
294	  const isNew = initSegment(session, state, key, createEntry);
295	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
296	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
297	  appendDelta(session, state[key]!, content);
298	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
299	}
300	
301	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
302	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
303	  markSuppressed(session, index);
304	  sendSkip(ws, index);
305	}
306	
307	function markSuppressed(session: ChatSession, index: number): void {
308	  const entry = session.entries[index];
309	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
310	}
311	
312	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
313	  if (state[key] !== null) return false;
314	  state[key] = appendEntry(session, createEntry());
315	  return true;
316	}
317	
318	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
319	  const index = state[key];
320	  if (index === null) return;
321	
322	  commitEntry(session, index);
323	  state[key] = null;
324	
325	  // Only what the client received can be retracted, and only assistant entries.
326	  if (state.suppressOutput) return;
327	
328	  sendCommit(ws, index);
329	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
330	}
331	
332	function processToolUseChunk(
333	  ws: WebSocket,
334	  session: ChatSession,
335	  toolCall: {name: string; input: Record<string, unknown>}
336	): void {
337	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
338	  const toolIndex = appendEntry(session, toolEntry);
339	  sendUpsert(ws, toolIndex, toolEntry);
340	}
341	
342	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
343	  for (const msg of clientMessages) {
344	    log.debug('stream', 'forwarding client message to frontend', {
345	      type: msg.type,
346	      index: 'index' in msg ? msg.index : undefined,
347	    });
348	    sendJson(ws, msg);
349	  }
350	}
351	
352	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
353	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
354	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
355	  commitOpenEntries(ws, session, state);
356	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
357	
358	  for (const idx of state.sentAssistantIndices) {
359	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
360	    markSuppressed(session, idx);
361	  }
362	
363	  state.sentAssistantIndices = [];
364	  state.suppressOutput = true;
365	}
366	
367	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
368	  flushHeldText(ws, session, state, parser);
369	  commitOpenEntries(ws, session, state);
370	}
371	
372	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
373	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
374	  for (const segment of parser.flush()) {
375	    handleTextSegment(ws, session, state, segment);
376	  }
377	}
378	
379	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
380	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
381	  const index = state[key];
382	  if (index === null) return;
383	  markTruncated(session, index);
384	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
385	  commitAndClear(ws, session, state, key);
386	}
387	
388	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
389	  commitAndClear(ws, session, state, 'thinkingIndex');
390	  commitAndClear(ws, session, state, 'assistantIndex');
391	}
392	
393	function handlePing(ws: WebSocket, timestamp: number): void {
394	  ws.send(JSON.stringify({type: 'pong', timestamp}));
395	}
