/**
 * no-flag-params — a boolean flag argument splits one function into two
 * behaviours selected at the call site. `render(true)` tells the reader
 * nothing; `renderCompact()` tells them everything. The house style wants one
 * function per behaviour, named for what it does.
 *
 * What counts, on the declaration side: a parameter whose TS annotation is
 * `boolean` (also `boolean | undefined` / `boolean | null`), or whose default
 * value is a `true`/`false` literal. On the call side: a bare `true`/`false`
 * literal passed as an argument to a call or `new` expression.
 *
 * Option `allowNamed` (default true): object-destructured parameters
 * (`{ force }: { force: boolean }`) and object-literal arguments
 * (`save({ force: true })`) are named, so they read at the call site and are
 * not flags. Set it to false to report those too.
 *
 * Detect-only: the fix is a second function, or a discriminated options
 * object — human judgment, not a codemod.
 */
const BOOLEAN_KEYWORD = "TSBooleanKeyword";
const NULLISH_KEYWORDS = new Set(["TSUndefinedKeyword", "TSNullKeyword"]);
function isBooleanTypeNode(typeNode) {
    if (!typeNode) {
        return false;
    }
    if (typeNode.type === BOOLEAN_KEYWORD) {
        return true;
    }
    if (typeNode.type !== "TSUnionType") {
        return false;
    }
    const members = typeNode.types.filter((member) => !NULLISH_KEYWORDS.has(member.type));
    return members.length === 1 && members[0].type === BOOLEAN_KEYWORD;
}
function isBooleanLiteral(node) {
    return node?.type === "Literal" && typeof node.value === "boolean";
}
function unwrapParameter(param) {
    if (param.type === "TSParameterProperty") {
        return param.parameter;
/**
 * max-member-chain — Law of Demeter. A chain like `a.b.c.d` or `a.b().c.d()`
 * reaches through collaborators the caller has no business knowing; the
 * caller should ask its direct collaborator for what it needs.
 *
 * Depth = number of `MemberExpression` hops from the chain's root. Computed
 * hops (`a[0].b`) and optional hops (`a?.b`) count like any other. Only the
 * OUTERMOST member expression of a chain is reported — an inner one whose
 * parent continues the chain (as the object of another member, or as the
 * callee of a call that is itself continued) is skipped.
 *
 * Exempt:
 *  - the root is `this` / `super`;
 *  - the root is a well-known global (`Math`, `JSON`, `Promise`, `Object`,
 *    `Array`, `Number`, `String`, `Reflect`, `process`, `console`,
 *    `globalThis`, `window`, `document`, `Symbol`, `Date`) or a name listed
 *    in option `allowRoots`;
 *  - every hop after the root is a call (`builder().a().b().c()` fluent
 *    chains return the same kind of thing at each step);
 *  - chains rooted in `import.meta`.
 *
 * Detect-only: the fix is a method on the direct collaborator.
 */
const DEFAULT_MAX = 2;
const CHAIN_TEXT_LIMIT = 60;
const DEFAULT_ALLOWED_ROOTS = new Set([
    "Math",
    "JSON",
    "Promise",
    "Object",
/**
 * callee-below-caller — place functions in the downward direction: a reader
 * meets the caller first and finds the callee below it. A file then reads like
 * a newspaper — headline at the top, detail as you scroll — instead of forcing
 * the reader to hold a pile of helpers in their head before the point arrives.
 *
 * What counts: only top-level `FunctionDeclaration`s (direct `Program` children,
 * including `export function`). For each, the FIRST reference in source order
 * that lives inside another top-level function names its caller; a callee whose
 * declaration sits ABOVE that caller is reported. Exemptions:
