      expect({frames: h.frames(), open: stillStreaming(h.session), answer}).toMatchObject({
        frames: [
          'upsert 0 user "hello"',
          'upsert 1 assistant ""',
          'delta 1 "partial answer"',
          'upsert 1 assistant "partial answer"',
          'commit 1',
          'error SERVER_ERROR',
          'stream_end',
        ],
        open: 0,
        answer: {role: 'assistant', content: 'partial answer', isStreaming: false},
